package com.corefilter.farmer.maps;

final class MapTransferPage {
    private MapTransferPage(){}
    static String html(String base){return """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ceiling Scout maps</title>
<style>body{margin:0;background:#101b20;color:#ddeadf;font:16px system-ui,sans-serif}main{max-width:880px;margin:36px auto;padding:0 22px 40px}h1{font-size:32px;margin:10px 0}h2{font-size:19px}p{color:#adc1c0;line-height:1.55}article,.guide{background:#1b3037;padding:20px;border-radius:14px;margin:18px 0}a,button{display:inline-block;background:#97e9c8;color:#10201c;border:0;border-radius:7px;padding:11px 15px;font:inherit;text-decoration:none;cursor:pointer;margin:4px 8px 4px 0}button{background:#354f56;color:#e4f0ed}small{display:block;overflow-wrap:anywhere;color:#adc1c0}img{width:100%;margin:12px 0;background:#101b20;border-radius:6px}label{display:block;margin-top:12px}input{max-width:100%}.status{color:#97e9c8}code{overflow-wrap:anywhere}</style>
<main><small>CEILING SCOUT / SAME WI-FI</small><h1>Your observed maps</h1><p>Each ZIP contains the map picture and its raw data. Empty areas are unknown, and separate unlinked sections stay separate.</p>
<div class="guide"><h2>Save all maps to your laptop</h2><p>Download the receiver, then run it in PowerShell. It saves each ZIP, checks its SHA-256, and only then asks the phone to remove that saved copy. Keep the sharing page open on your phone.</p><a href="./receive-maps.ps1">Download receiver</a><p>After downloading, open PowerShell and paste:</p><code>powershell -ExecutionPolicy Bypass -File "$HOME\\Downloads\\receive-maps.ps1"</code></div>
<p>Prefer a manual download? Download a ZIP below, then choose that saved ZIP to verify and remove its phone copy. Downloading alone never deletes anything.</p><button id="refresh">Refresh maps</button><p id="summary">Loading…</p><div id="maps"></div></main>
<script>
const base=__BASE__,token=base.substring(base.lastIndexOf('/')+1);
const encode=s=>encodeURIComponent(s),byId=s=>document.getElementById(s);
async function digest(buffer){if(globalThis.crypto&&crypto.subtle){const d=new Uint8Array(await crypto.subtle.digest('SHA-256',buffer));return Array.from(d,x=>x.toString(16).padStart(2,'0')).join('');}return sha256(new Uint8Array(buffer));}
function sha256(bytes){const K=[0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2];let h=[0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19];const size=Math.ceil((bytes.length+9)/64)*64,p=new Uint8Array(size),view=new DataView(p.buffer),w=new Uint32Array(64);p.set(bytes);p[bytes.length]=128;view.setUint32(size-8,Math.floor(bytes.length/0x20000000));view.setUint32(size-4,(bytes.length*8)>>>0);const rr=(x,n)=>(x>>>n)|(x<<(32-n));for(let off=0;off<size;off+=64){for(let i=0;i<16;i++)w[i]=view.getUint32(off+i*4);for(let i=16;i<64;i++){let a=w[i-15],b=w[i-2];w[i]=(w[i-16]+(rr(a,7)^rr(a,18)^(a>>>3))+w[i-7]+(rr(b,17)^rr(b,19)^(b>>>10)))>>>0;}let[a,b,c,d,e,f,g,j]=h;for(let i=0;i<64;i++){const t1=(j+(rr(e,6)^rr(e,11)^rr(e,25))+((e&f)^(~e&g))+K[i]+w[i])>>>0,t2=((rr(a,2)^rr(a,13)^rr(a,22))+((a&b)^(a&c)^(b&c)))>>>0;j=g;g=f;f=e;e=(d+t1)>>>0;d=c;c=b;b=a;a=(t1+t2)>>>0;}h=h.map((v,i)=>(v+[a,b,c,d,e,f,g,j][i])>>>0);}return h.map(v=>v.toString(16).padStart(8,'0')).join('');}
async function refresh(){try{const response=await fetch(base+'/api/maps',{cache:'no-store'});if(!response.ok)throw Error('Sharing session ended');const data=await response.json(),maps=data.maps;byId('summary').textContent=maps.length+' map bundle'+(maps.length===1?'':'s')+' stored on the phone';byId('maps').replaceChildren();for(const map of maps.reverse()){const article=document.createElement('article'),title=document.createElement('h2');title.textContent=map.id;article.append(title);const detail=document.createElement('small');detail.textContent=(map.bytes/1048576).toFixed(2)+' MB · SHA-256 '+map.sha256;article.append(detail);const image=document.createElement('img');image.loading='lazy';image.alt='Observed map sections';image.src=base+'/preview/'+encode(map.id);article.append(image);const link=document.createElement('a');link.href=base+'/download/'+encode(map.id);link.textContent='Download ZIP';article.append(link);const label=document.createElement('label');label.textContent='Verify a saved ZIP and remove its phone copy';const input=document.createElement('input');input.type='file';input.accept='.zip,application/zip';label.append(document.createElement('br'),input);article.append(label);const status=document.createElement('p');status.className='status';article.append(status);input.onchange=async()=>{const file=input.files[0];if(!file)return;input.disabled=true;try{if(file.size!==map.bytes)throw Error('File size differs. Phone copy retained.');status.textContent='Checking your saved ZIP…';const hash=await digest(await file.arrayBuffer());if(hash!==map.sha256)throw Error('Checksum differs. Phone copy retained.');if(!confirm('Saved ZIP verified. Remove this exact bundle from the phone?')){status.textContent='Verified. Phone copy retained.';return;}const ack=await fetch(base+'/api/ack',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+token},body:JSON.stringify({id:map.id,sha256:hash})});if(!ack.ok)throw Error('Receipt not confirmed. Phone copy may remain; refresh to check.');status.textContent='Saved ZIP verified; phone copy removed.';input.remove();link.remove();}catch(error){status.textContent=error.message;}finally{input.disabled=false;}};byId('maps').append(article);}}catch(error){byId('summary').textContent=error.message+' — reopen sharing on your phone if needed.';}}
byId('refresh').onclick=refresh;refresh();
</script></html>
""".replace("__BASE__",org.json.JSONObject.quote(base));}
}
